import{_ as t,c as o,o as a,ag as s}from"./chunks/framework.dvv-DFtf.js";const h=JSON.parse('{"title":"AI Assistant","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-assistant.md","filePath":"features/ai-assistant.md"}'),n={name:"features/ai-assistant.md"};function i(r,e,c,d,l,u){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ai-assistant" tabindex="-1">AI Assistant <a class="header-anchor" href="#ai-assistant" aria-label="Permalink to &quot;AI Assistant&quot;">​</a></h1><p>Kubby AI Assistant feature is very lightweight and pragmatic. If configured, it lets you launch an external AI coding tool of your choice with your current Kubernetes context, enabling natural language queries and assistance for managing your cluster. If not configured the button and action are not visible in the UI and you can simply ignore the feature.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Press <code>A</code> to launch your configured AI assistant. Kubby prepares a workspace with your current context, namespace, and selected resource, then opens your preferred AI tool.</p><h2 id="supported-tools" tabindex="-1">Supported Tools <a class="header-anchor" href="#supported-tools" aria-label="Permalink to &quot;Supported Tools&quot;">​</a></h2><p>Kubby supports five AI coding assistants:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Config Value</th><th>Description</th></tr></thead><tbody><tr><td>Cursor Agent</td><td><code>cursor-agent</code></td><td>Cursor&#39;s CLI agent (terminal-based)</td></tr><tr><td>Cursor IDE</td><td><code>cursor</code></td><td>Opens a new Cursor window</td></tr><tr><td>Claude Code</td><td><code>claude</code></td><td>Anthropic&#39;s Claude CLI</td></tr><tr><td>Augment</td><td><code>augment</code></td><td>Augment&#39;s auggie CLI</td></tr><tr><td>Codex</td><td><code>codex</code></td><td>OpenAI&#39;s Codex CLI</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Add the <code>ai</code> section to your <code>kubby_config.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cursor-agent</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Which AI tool to launch</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Agent</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Custom button label (default: &quot;AI&quot;)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  readOnly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Restrict kubectl to safe commands, defaults to true if not set</span></span></code></pre></div><p>Once configured, the button appears in the shortcuts bar with your custom name (or &quot;AI&quot; by default). Hovering shows the actual tool being used.</p><h3 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to &quot;Configuration Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tool</code></td><td>string</td><td>(required)</td><td>AI tool to launch: <code>cursor-agent</code>, <code>cursor</code>, <code>claude</code>, <code>augment</code>, or <code>codex</code></td></tr><tr><td><code>name</code></td><td>string</td><td><code>&quot;AI&quot;</code></td><td>Custom button label (e.g., &quot;Agent&quot; for Cursor Agent)</td></tr><tr><td><code>readOnly</code></td><td>boolean</td><td><code>true</code></td><td>Restrict kubectl to read-only commands</td></tr></tbody></table><h2 id="read-only-mode" tabindex="-1">Read-Only Mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to &quot;Read-Only Mode&quot;">​</a></h2><p>When <code>readOnly: true</code> (the default), Kubby creates a kubectl wrapper that:</p><p><strong>Allows only safe commands:</strong></p><ul><li><code>get</code>, <code>describe</code>, <code>logs</code>, <code>explain</code>, <code>top</code></li><li><code>api-resources</code>, <code>api-versions</code>, <code>cluster-info</code></li><li><code>config view</code>, <code>config get-contexts</code>, <code>config current-context</code></li><li><code>version</code>, <code>auth can-i</code>, <code>diff</code></li></ul><p><strong>Blocks modifying commands:</strong></p><ul><li><code>apply</code>, <code>delete</code>, <code>edit</code>, <code>patch</code></li><li><code>scale</code>, <code>rollout</code>, <code>exec</code>, <code>run</code></li><li>Context/namespace switching (<code>config use-context</code>, <code>config set-context</code>)</li></ul><p><strong>Locks context and namespace:</strong></p><ul><li>The wrapper only allows kubectl commands targeting the configured context and namespace</li><li>Prevents the AI from accidentally operating on the wrong cluster</li></ul><p>You can inspect the <code>kubectl</code> wrapper script in <code>~/.kubby/ai/bin/kubectl</code>.</p><div class="tip custom-block"><p class="custom-block-title">Safety First</p><p>Enable read-only mode for production clusters. The AI can still help you understand resources and debug issues. ⚠️ As with any AI tool, be mindfully that this is not a 100% safe protection, the current models are very smart and can escape any protection by directly modifying files or system configuration.</p></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When you press <code>A</code>, Kubby:</p><ol><li><strong>Creates the AI workspace</strong> at <code>~/.kubby/ai/</code> with configuration files for your chosen tool</li><li><strong>Writes <code>context.md</code></strong> containing the current context, namespace, resource type, and selected resource</li><li><strong>Configures the kubectl wrapper</strong> based on your read-only setting</li><li><strong>Launches your AI tool</strong> with the Kubby bin directory prepended to PATH</li></ol><p>The kubectl wrapper at <code>~/.kubby/ai/bin/kubectl</code> transparently intercepts all <code>kubectl</code> commands via PATH. The AI uses kubectl normally without needing special instructions about the wrapper.</p><h2 id="workspace-structure" tabindex="-1">Workspace Structure <a class="header-anchor" href="#workspace-structure" aria-label="Permalink to &quot;Workspace Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.kubby/ai/</span></span>
<span class="line"><span>├── context.md          # Current Kubernetes context (updated each launch)</span></span>
<span class="line"><span>├── bin/</span></span>
<span class="line"><span>│   └── kubectl         # Wrapper script (prepended to PATH, intercepts kubectl)</span></span>
<span class="line"><span>├── .cursor/</span></span>
<span class="line"><span>│   └── mcp.json        # MCP configuration for Cursor</span></span>
<span class="line"><span>├── .cursorrules        # Instructions for Cursor</span></span>
<span class="line"><span>├── CLAUDE.md           # Instructions for Claude Code</span></span>
<span class="line"><span>├── AGENTS.md           # Instructions for Codex</span></span>
<span class="line"><span>└── augment.yaml        # Configuration for Augment</span></span></code></pre></div><p>The <code>bin/kubectl</code> wrapper is prepended to PATH so it intercepts all <code>kubectl</code> calls transparently. When <code>readOnly: true</code>, the wrapper enforces security policies:</p><ul><li>Only allows safe, read-only kubectl commands</li><li>Blocks commands that modify resources</li><li>Locks context and namespace to prevent accidental cross-cluster operations</li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h3><ol><li>Navigate to a resource in the Resource List</li><li>Press <code>A</code> to launch the AI assistant</li><li>The AI opens with your current context pre-loaded</li><li>Ask questions like: <ul><li>&quot;What&#39;s the current replica count for this deployment?&quot;</li><li>&quot;Show me the recent events for this pod&quot;</li><li>&quot;Why is this pod in CrashLoopBackOff?&quot;</li></ul></li></ol><h3 id="other-example-queries" tabindex="-1">Other example Queries <a class="header-anchor" href="#other-example-queries" aria-label="Permalink to &quot;Other example Queries&quot;">​</a></h3><p>With context on a deployment:</p><ul><li>&quot;Scale this deployment to 5 replicas&quot; (requires readOnly: false)</li><li>&quot;What images are the containers using?&quot;</li><li>&quot;Show me the resource limits&quot;</li></ul><p>With context on a pod:</p><ul><li>&quot;Are errors in logs in the last hour?&quot;</li><li>&quot;What&#39;s consuming the most memory?&quot;</li><li>&quot;Describe the pod&#39;s restart history&quot;</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Context-Aware Assistance</p><p>The AI knows your current context, namespace, and selected resource. You don&#39;t need to specify them in your questions.</p></div><div class="tip custom-block"><p class="custom-block-title">Tool Installation</p><p>Make sure your chosen AI tool&#39;s CLI is installed and available in your PATH. <code>git</code> is required to initialize Kubby <code>ai</code> folder. Other tools may be needed depending on the AI tool.</p></div>`,42)])])}const g=t(n,[["render",i]]);export{h as __pageData,g as default};
